bash: cd /app && sh setup-mailing-list.sh 2>&1 | tail -10; echo "setup_exit=$?"; sleep 3; python3 - <<'EOF'
import socket
for p in (25, 8024):
    s=socket.socket(); s.settimeout(2)
    try: s.connect(('127.0.0.1',p)); print(p,'open')
    except Exception as e: print(p,'CLOSED',e)
    finally: s.close()
EOF

